import{f as a,o as e,c as o,a4 as d}from"./chunks/framework.6QvN0vQS.js";const u=JSON.parse('{"title":"CoopApps — Lo nuevo, más aplicativos y más capacidad (vs ProCoop legacy)","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/lo-nuevo-coopapps-vs-procoop-PROMPT-COMPLETO-CLAUDE.md","filePath":"presentacion-stakeholders/lo-nuevo-coopapps-vs-procoop-PROMPT-COMPLETO-CLAUDE.md","lastUpdated":null}'),r={name:"presentacion-stakeholders/lo-nuevo-coopapps-vs-procoop-PROMPT-COMPLETO-CLAUDE.md"};function n(i,t,s,l,c,p){return e(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="coopapps-—-lo-nuevo-mas-aplicativos-y-mas-capacidad-vs-procoop-legacy" tabindex="-1">CoopApps — Lo nuevo, más aplicativos y más capacidad (vs ProCoop legacy) <a class="header-anchor" href="#coopapps-—-lo-nuevo-mas-aplicativos-y-mas-capacidad-vs-procoop-legacy" aria-label="Permalink to &quot;CoopApps — Lo nuevo, más aplicativos y más capacidad (vs ProCoop legacy)&quot;">​</a></h1><p><strong>Uso:</strong> copiar <strong>todo</strong> el bloque de la §A en Claude. <strong>No hace falta adjuntar</strong> otros archivos: el contenido de cada slide está en la §B (códigos <strong>IMG-N00…N23</strong>).</p><p><strong>Por slide (recomendado):</strong> carpeta <a href="./img-n-lotes/README"><code>img-n-lotes/</code></a> — pegar una vez <code>PROMPT-A-pegar-primero.txt</code>, luego <code>Generá IMG-Nxx</code> con el <code>.md</code> del lote. Regenerar lotes: <code>python scripts/export_img_n_lotes.py</code>.</p><p><strong>Complementa</strong> (no reemplaza) el comparativo menú a menú: <a href="./comparativo-funcional-megaspec-unificado"><code>comparativo-funcional-megaspec-unificado.md</code></a> + IMG-F.</p><p><strong>Códigos:</strong> IMG-N00…N23 (25 diapositivas posibles).</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>19-11-2026</td></tr><tr><td>Enfoque</td><td><strong>Delta:</strong> qué suma CoopApps que ProCoop no tiene o tiene acotado</td></tr><tr><td>Idioma slides</td><td>Español Argentina; <strong>cero</strong> códigos M01, T04, PC-, olas, SM- en tabla visible</td></tr><tr><td>Versión revisión</td><td>1.1 — completitud marketing + honestidad (nov 2026)</td></tr></tbody></table><h3 id="checklist-de-calidad-antes-de-presentar" tabindex="-1">Checklist de calidad (antes de presentar) <a class="header-anchor" href="#checklist-de-calidad-antes-de-presentar" aria-label="Permalink to &quot;Checklist de calidad (antes de presentar)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Criterio</th><th>¿Cumple?</th></tr></thead><tbody><tr><td>Respeto a ProCoop (no “no tiene nada”)</td><td>Sí — N01, N21, tono del prompt</td></tr><tr><td>Número ancla 119/120</td><td>Sí — N00, N01, N22 (no “120 sin matices”)</td></tr><tr><td>8 aplicativos</td><td>Sí — N02, N20</td></tr><tr><td>17 familias de servicio</td><td>Sí — N12 + <strong>N12b</strong> (completa las 17)</td></tr><tr><td>API sin overselling</td><td>Sí — N13 ámbar, N21</td></tr><tr><td>Dolores del relevamiento</td><td>Sí — N15 (7) + <strong>N15b</strong> (otros pedidos)</td></tr><tr><td>Inventario “plus”</td><td>Sí — N18–N19 (20 ítems verificados, no 40 inventados)</td></tr><tr><td>Por audiencia (marketing)</td><td>Sí — <strong>N23</strong> consejo / socio / operación</td></tr></tbody></table><hr><h2 id="a-bloque-para-copiar-y-pegar-en-claude-primero" tabindex="-1">A. Bloque para copiar y pegar en Claude (primero) <a class="header-anchor" href="#a-bloque-para-copiar-y-pegar-en-claude-primero" aria-label="Permalink to &quot;A. Bloque para copiar y pegar en Claude (primero)&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sos diseñador de slides ejecutivas (1920×1080, HTML+SVG exportable a PNG) para cooperativas de servicios de Argentina.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TEMA DEL DECK: no es repetir el menú ProCoop función por función. Es mostrar QUÉ MÁS TRAE CoopApps:</span></span>
<span class="line"><span>- más aplicativos y canales,</span></span>
<span class="line"><span>- funciones nuevas o muy ampliadas,</span></span>
<span class="line"><span>- capacidades que ProCoop no tiene como producto unificado.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TONO: ProCoop es competidor respetable y cubre el negocio (119 de 120 ítems de menú tienen destino). Este deck muestra el **plus**, sin humillar al legacy.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AUDIENCIAS EN EL MISMO SLIDE:</span></span>
<span class="line"><span>- Gerencia lee “Por qué importa”.</span></span>
<span class="line"><span>- Operación lee “Hoy en ProCoop” y “Qué suma CoopApps”.</span></span>
<span class="line"><span>- Técnica: solo si pido pie con refs.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PROHIBIDO en texto visible grande ===</span></span>
<span class="line"><span>M01, T10, O11, PC-077, SM-, DFA, RF-, “equivalente en Mxx”.</span></span>
<span class="line"><span>Palabras vacías: revolucionario, disruptivo, líder, el mejor, sin ProCoop, reemplazo inmediato, API desde el día 1, mismas pantallas, tiempo real al milisegundo.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== MARKETING SIN MENTIR (cada slide) ===</span></span>
<span class="line"><span>- Título = beneficio en lenguaje humano (no técnico).</span></span>
<span class="line"><span>- Opcional bajo el título: **Gancho** (1 frase ≤ 20 palabras) que responda “¿y eso qué me da?”.</span></span>
<span class="line"><span>- En tablas, si hay espacio: columna corta **Por qué importa** (1 línea; puede ir en verde tenue).</span></span>
<span class="line"><span>- Número protagonista solo si está en el catálogo (119/120, 8 apps, 17 servicios, 4.200+ requisitos, 71 trámites autogestión).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PERMITIDO (con honestidad) ===</span></span>
<span class="line"><span>“API abierta documentada” → decir “planificada para la etapa final del producto” si la fila lo indica.</span></span>
<span class="line"><span>“ProCoop sí tiene CoopOnline / P-Móvil” → el mensaje es calidad y modelo, no “no tienen app”.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PALETA ===</span></span>
<span class="line"><span>Títulos #2F343A; ProCoop/Hoy #6B7280 sobre #E5E7EB; CoopApps #1F2937 con acento #2E7D32 en lo nuevo; ámbar #B7791F solo para “planificado / a validar en calendario”.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== LAYOUT POR TIPO ===</span></span>
<span class="line"><span>1) Tabla 3 columnas: Tema | Hoy en ProCoop | Qué suma CoopApps (+ etiqueta Nuevo | Ampliado | Modelo distinto)</span></span>
<span class="line"><span>2) Lista comparativa: máximo 7–9 filas por slide</span></span>
<span class="line"><span>3) Viñetas: máximo 6, una idea por línea</span></span>
<span class="line"><span>Pie fijo: &quot;Fuente: especificación CoopApps + relevamiento ProCoop DEMO (nov 2026)&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== CATÁLOGO (contenido en el mismo mensaje del usuario, sección B) ===</span></span>
<span class="line"><span>Cuando escriba &quot;Generá IMG-N12&quot;, buscá el encabezado ## IMG-N12 más abajo en el documento pegado y renderizá TODO su contenido. Textos literales; no acortar con códigos.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tras cada slide: 3 bullets para consejo + 3 para jefe de área (sin códigos).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Confirmá y esperá &quot;Generá IMG-N00&quot; o el código que pida.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br></div></div><p><strong>Después del bloque anterior</strong>, en el <strong>mismo chat</strong>, pegá también la <strong>§B completa</strong> (desde <code>## B. Catálogo</code> hasta el final de este archivo), <strong>o</strong> adjuntá este archivo entero.</p><hr><h2 id="b-catalogo-img-n00-img-n23" tabindex="-1">B. Catálogo IMG-N00 … IMG-N23 <a class="header-anchor" href="#b-catalogo-img-n00-img-n23" aria-label="Permalink to &quot;B. Catálogo IMG-N00 … IMG-N23&quot;">​</a></h2><hr><h2 id="img-n00-—-portada-del-deck-lo-nuevo" tabindex="-1">IMG-N00 — Portada del deck “lo nuevo” <a class="header-anchor" href="#img-n00-—-portada-del-deck-lo-nuevo" aria-label="Permalink to &quot;IMG-N00 — Portada del deck “lo nuevo”&quot;">​</a></h2><p><strong>Título:</strong> CoopApps: el mismo negocio, más plataforma<br><strong>Subtítulo:</strong> Más aplicativos · más canales · más capacidades — sin perder lo que hoy funciona<br><strong>Gancho:</strong> Lo que ProCoop hace en escritorio; lo que suma la nube, la marca y el socio en el circuito.<br><strong>Centro (3 líneas):</strong></p><ul><li>Mismo alcance del menú relevado (119/120).</li><li>Este material muestra el <strong>plus</strong>: nube, marca, campo, comunidad, institucional, datos. <strong>Pie:</strong> No reemplaza el comparativo función por función (deck IMG-F).</li></ul><hr><h2 id="img-n01-—-mensaje-honesto" tabindex="-1">IMG-N01 — Mensaje honesto <a class="header-anchor" href="#img-n01-—-mensaje-honesto" aria-label="Permalink to &quot;IMG-N01 — Mensaje honesto&quot;">​</a></h2><p><strong>Título:</strong> ProCoop hace el negocio. CoopApps suma plataforma.</p><table tabindex="0"><thead><tr><th>Idea</th><th>Texto</th></tr></thead><tbody><tr><td>Reconocimiento</td><td>Facturación masiva, multiservicio, mora, compras, sueldos: ProCoop es profundo y conocido.</td></tr><tr><td>Alcance</td><td><strong>119 de 120</strong> funciones del menú relevado con destino en CoopApps; cero ítems sin especificación. La restante es administrar la base local (pasa al proveedor en la nube).</td></tr><tr><td>Este deck</td><td>Explica qué <strong>nuevo</strong> o <strong>muy ampliado</strong> trae CoopApps respecto del escritorio + CoopOnline + P-Móvil.</td></tr></tbody></table><hr><h2 id="img-n02-—-ocho-aplicativos-vs-el-modelo-legacy" tabindex="-1">IMG-N02 — Ocho aplicativos vs el modelo legacy <a class="header-anchor" href="#img-n02-—-ocho-aplicativos-vs-el-modelo-legacy" aria-label="Permalink to &quot;IMG-N02 — Ocho aplicativos vs el modelo legacy&quot;">​</a></h2><p><strong>Título:</strong> Una cooperativa, ocho formas de trabajar (ProCoop concentraba casi todo en escritorio)</p><table tabindex="0"><thead><tr><th>Aplicación CoopApps</th><th>Hoy con ProCoop</th><th>Qué suma</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Gestión web para el personal</td><td>Programa instalado en cada PC</td><td>Misma versión para todos; navegador; sin parque local</td><td>Modelo distinto</td></tr><tr><td>Portal y app del socio</td><td>CoopOnline sobre copia; web genérica del proveedor</td><td>Mismo dato que caja; logo y colores propios; app instalable</td><td>Ampliado</td></tr><tr><td>Espacio del empleado</td><td>Recibos y consultas limitadas</td><td>Recibos, licencias y documentación sin mezclar al socio</td><td>Nuevo</td></tr><tr><td>App de campo (sin señal)</td><td>P-Móvil sobre copia de datos</td><td>Una sola app: técnico, lecturista, cobrador, inspector</td><td>Ampliado</td></tr><tr><td>Sitio público / landing</td><td>Web compartida entre cooperativas</td><td>Dominio propio; bloques; borrador y publicación</td><td>Nuevo</td></tr><tr><td>Tótem en sucursal</td><td>Solo parcial vía turnero</td><td>Modo tótem dedicado para autogestión</td><td>Ampliado</td></tr><tr><td>Consola del proveedor SaaS</td><td>No existe como producto</td><td>Operación de plataforma (no es el día a día de caja)</td><td>Nuevo</td></tr><tr><td>API para integradores de la cooperativa</td><td>Integra y exportaciones; sin API por recurso administrable</td><td>API versionada con permisos de la cooperativa (etapa final del plan)</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n03-—-plataforma-y-operacion-sin-servidor-propio" tabindex="-1">IMG-N03 — Plataforma y operación sin servidor propio <a class="header-anchor" href="#img-n03-—-plataforma-y-operacion-sin-servidor-propio" aria-label="Permalink to &quot;IMG-N03 — Plataforma y operación sin servidor propio&quot;">​</a></h2><p><strong>Título:</strong> De “la PC del servidor y del Agente” a servicio en la nube</p><table tabindex="0"><thead><tr><th>Tema</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Instalación</td><td>En cada PC y servidor de la cooperativa</td><td>Acceso web y apps; el tenant no opera SQL Server</td><td>Modelo distinto</td></tr><tr><td>Actualizaciones</td><td>Actualizar equipo por equipo</td><td>Una versión para todas las sedes</td><td>Modelo distinto</td></tr><tr><td>Copia de seguridad</td><td>Menú que depende del usuario</td><td>Copia diaria automática; ensayos de restauración</td><td>Modelo distinto</td></tr><tr><td>Ambiente de prueba</td><td>Demo o copia manual</td><td>Sandbox por cooperativa para probar sin tocar producción</td><td>Nuevo</td></tr><tr><td>Soporte</td><td>Acceso remoto sin caso claro</td><td>Ticket numerado; acceso temporal revocable y auditado</td><td>Ampliado</td></tr><tr><td>Salud del servicio</td><td>Implícito</td><td>Tablero de salud del tenant para gerencia y TI</td><td>Nuevo</td></tr><tr><td>Si un día se va del proveedor</td><td>Backup SQL manual</td><td>Exportación completa de los datos de la cooperativa</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n04-—-un-solo-dato-fin-de-la-replica" tabindex="-1">IMG-N04 — Un solo dato (fin de la réplica) <a class="header-anchor" href="#img-n04-—-un-solo-dato-fin-de-la-replica" aria-label="Permalink to &quot;IMG-N04 — Un solo dato (fin de la réplica)&quot;">​</a></h2><p><strong>Título:</strong> El socio, caja y facturación miran la misma cuenta</p><table tabindex="0"><thead><tr><th>Tema</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Portal del socio</td><td>Copia a base externa; puede desfasarse</td><td>Sin réplica intermedia: saldo portal = saldo caja</td><td>Ampliado</td></tr><tr><td>Pagos web</td><td>Confirmación indirecta vía sincronización</td><td>Cobro confirmado antes de imputar y reconectar</td><td>Ampliado</td></tr><tr><td>App móvil de campo</td><td>Trabaja sobre copia</td><td>Misma base operativa; conflictos supervisados al sincronizar</td><td>Ampliado</td></tr><tr><td>PDF y comprobantes</td><td>Rutas FTP/S3 y jobs locales</td><td>Generación y entrega desde la nube</td><td>Modelo distinto</td></tr><tr><td>Riesgo operativo</td><td>“Se cayó la PC del Agente”</td><td>Jobs en nube con reintentos</td><td>Modelo distinto</td></tr></tbody></table><hr><h2 id="img-n05-—-sin-boton-equivalente-en-el-menu-escritorio" tabindex="-1">IMG-N05 — Sin botón equivalente en el menú escritorio <a class="header-anchor" href="#img-n05-—-sin-boton-equivalente-en-el-menu-escritorio" aria-label="Permalink to &quot;IMG-N05 — Sin botón equivalente en el menú escritorio&quot;">​</a></h2><p><strong>Título:</strong> Capacidades nuevas que no son un ítem del menú ProCoop</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Sitio público por bloques</td><td>Web genérica del proveedor</td><td>Dominio propio; publicar borrador sin programar</td><td>Nuevo</td></tr><tr><td>Asamblea con quórum en vivo</td><td>Actas y listas manuales</td><td>Credencial y quórum en tiempo real</td><td>Nuevo</td></tr><tr><td>Incidente masivo (corte de zona)</td><td>Miles de reclamos iguales</td><td>Un incidente; muchos socios vinculados</td><td>Nuevo</td></tr><tr><td>Bóveda de credenciales</td><td>Claves en programa o tablas</td><td>Credenciales segregadas prueba/producción</td><td>Nuevo</td></tr><tr><td>Indicadores certificados</td><td>Excel distinto al tablero</td><td>Mismo número en portal, gerencia y reportes</td><td>Nuevo</td></tr><tr><td>Contabilidad en convivencia</td><td>Apagar un sistema o romper ejercicio</td><td>Contabilidad paralela hasta cerrar migración</td><td>Nuevo</td></tr><tr><td>Diccionario propio</td><td>Textos fijos del sistema</td><td>Socio/asociado/usuario según la cooperativa</td><td>Nuevo</td></tr><tr><td>Comunidad (muro, encuestas)</td><td>SMS aislado en Herramientas</td><td>Campañas, avisos por zona, eventos</td><td>Nuevo</td></tr></tbody></table><hr><h2 id="img-n06-—-socio-y-autogestion-1-2" tabindex="-1">IMG-N06 — Socio y autogestión (1/2) <a class="header-anchor" href="#img-n06-—-socio-y-autogestion-1-2" aria-label="Permalink to &quot;IMG-N06 — Socio y autogestión (1/2)&quot;">​</a></h2><p><strong>Título:</strong> Más trámites digitales con marca de la cooperativa</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop / CoopOnline</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Ver facturas y PDF</td><td>Sí, sobre réplica</td><td>Sí, desde el origen operativo</td><td>Ampliado</td></tr><tr><td>Pagar y prepagar web</td><td>Sí, con sincronización indirecta</td><td>Pago con confirmación real antes de imputar</td><td>Ampliado</td></tr><tr><td>Contratación digital</td><td>Parcial</td><td>Ciclo con factibilidad, turno y seguimiento</td><td>Ampliado</td></tr><tr><td>Estado de visita técnica</td><td>Limitado</td><td>Estados visibles para el socio en portal/app</td><td>Ampliado</td></tr><tr><td>Baja de servicio</td><td>Variable por configuración</td><td>Plazos regulatorios explícitos (24/72 h según trámite)</td><td>Ampliado</td></tr><tr><td>Autolectura y prepago</td><td>Limitado</td><td>Foto, reglas y conciliación con facturación</td><td>Ampliado</td></tr><tr><td>Representantes y permisos</td><td>Básico</td><td>Quién puede hacer qué, por acción</td><td>Ampliado</td></tr><tr><td>Pago por un tercero</td><td>Riesgo de ver cuenta ajena</td><td>Pago sin exponer datos de otro titular</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n07-—-socio-y-autogestion-2-2" tabindex="-1">IMG-N07 — Socio y autogestión (2/2) <a class="header-anchor" href="#img-n07-—-socio-y-autogestion-2-2" aria-label="Permalink to &quot;IMG-N07 — Socio y autogestión (2/2)&quot;">​</a></h2><p><strong>Título:</strong> Accesibilidad, filas y confianza</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop / CoopOnline</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Marca en app instalable</td><td>Portal compartido, poca identidad</td><td>Nombre, ícono y colores de la cooperativa</td><td>Ampliado</td></tr><tr><td>Empleado vs socio</td><td>Mezclado en canales</td><td>Espacio empleado separado del socio</td><td>Nuevo</td></tr><tr><td>Vincular cuentas al migrar</td><td>Depende de dueño de copia externa</td><td>Código corto; anti-enumeración</td><td>Ampliado</td></tr><tr><td>Consulta sin login completo</td><td>Poco formalizado</td><td>Consulta y pago con datos enmascarados</td><td>Ampliado</td></tr><tr><td>Accesibilidad</td><td>No verificada como estándar</td><td>Objetivo WCAG 2.2 AA en portal</td><td>Ampliado</td></tr><tr><td>Turno online</td><td>Turnero presencial fuerte</td><td>Reserva web + tótem + box</td><td>Ampliado</td></tr><tr><td>Avisos de corte</td><td>Masivos o genéricos</td><td>Solo a socios realmente afectados</td><td>Ampliado</td></tr><tr><td>Encuesta en factura (NPS)</td><td>No unificado</td><td>Medición post-gestión en canal digital</td><td>Nuevo</td></tr></tbody></table><blockquote><p>Referencia interna (no en slide): ~71 tipos de autogestión especificados en portal vs capacidades históricas de CoopOnline.</p></blockquote><hr><h2 id="img-n08-—-personal-y-gestion-interna-1-2" tabindex="-1">IMG-N08 — Personal y gestión interna (1/2) <a class="header-anchor" href="#img-n08-—-personal-y-gestion-interna-1-2" aria-label="Permalink to &quot;IMG-N08 — Personal y gestión interna (1/2)&quot;">​</a></h2><p><strong>Título:</strong> Más control sin más menús opacos</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Parámetros</td><td>Miles de claves numéricas</td><td>Nombre, tipo, vigencia e historial</td><td>Ampliado</td></tr><tr><td>Simular antes de publicar tarifa/parámetro</td><td>No formal</td><td>Vista previa antes de impactar producción</td><td>Nuevo</td></tr><tr><td>Aprobaciones</td><td>Autorización puntual de operación</td><td>Circuitos por monto, doble firma, bandeja única</td><td>Ampliado</td></tr><tr><td>Expediente digital</td><td>Reclamos y mesa dispersos</td><td>Trámite con documentos y plazos</td><td>Ampliado</td></tr><tr><td>Firma en gestiones</td><td>Limitada</td><td>Firma electrónica/digital con QR donde corresponde</td><td>Ampliado</td></tr><tr><td>Buscador de funciones</td><td>Menú fijo 9 pestañas</td><td>Búsqueda global estilo “como ProCoop pero en web”</td><td>Ampliado</td></tr><tr><td>Permisos</td><td>Perfil = menú + tablas</td><td>Rol por acción; plantillas ajustables</td><td>Modelo distinto</td></tr><tr><td>Auditoría</td><td>Login y algunos cambios</td><td>Cadena inmutable con valor anterior y nuevo</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n09-—-personal-y-gestion-interna-2-2" tabindex="-1">IMG-N09 — Personal y gestión interna (2/2) <a class="header-anchor" href="#img-n09-—-personal-y-gestion-interna-2-2" aria-label="Permalink to &quot;IMG-N09 — Personal y gestión interna (2/2)&quot;">​</a></h2><p><strong>Título:</strong> Compras, campo, institucional</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Portal del proveedor</td><td>No como portal</td><td>El proveedor carga y consulta su circuito</td><td>Nuevo</td></tr><tr><td>Anti-fraude en CBU</td><td>Control manual</td><td>Alerta si cambia CBU antes del pago</td><td>Nuevo</td></tr><tr><td>Factura compra asistida</td><td>Carga manual</td><td>Sugerencia de borrador (la persona valida)</td><td>Ampliado</td></tr><tr><td>Stock por serie</td><td>Trazabilidad variable</td><td>Saber qué módem/ONU está en qué domicilio</td><td>Ampliado</td></tr><tr><td>Asistente WhatsApp en atención</td><td>No integrado</td><td>Con verificación; no reemplaza al operador</td><td>Nuevo</td></tr><tr><td>Incidente único masivo</td><td>Muchos tickets iguales</td><td>Un incidente, N socios</td><td>Nuevo</td></tr><tr><td>Asambleas</td><td>Tablas e informes</td><td>Quórum en vivo; credencial QR</td><td>Nuevo</td></tr><tr><td>Capital e institucional</td><td>Disperso en tablas</td><td>Asamblea, capital, actas integradas</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n10-—-facturacion-cobranza-y-mora-mas-alla-de-igual" tabindex="-1">IMG-N10 — Facturación, cobranza y mora (más allá de “igual”) <a class="header-anchor" href="#img-n10-—-facturacion-cobranza-y-mora-mas-alla-de-igual" aria-label="Permalink to &quot;IMG-N10 — Facturación, cobranza y mora (más allá de “igual”)&quot;">​</a></h2><p><strong>Título:</strong> Mismos comprobantes, más control</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Emisión masiva</td><td>Muy capaz (DEMO ~12,5k comprobantes)</td><td>Lote con universo congelado; excepciones visibles</td><td>Ampliado</td></tr><tr><td>Prefactura y excepciones</td><td>Parcial</td><td>Quién no entra al lote y por qué</td><td>Ampliado</td></tr><tr><td>Explicar importe al socio</td><td>Saltos entre lectura y factura</td><td>Trazabilidad lectura → tarifa → renglón</td><td>Ampliado</td></tr><tr><td>Cobro sin guardar tarjeta</td><td>Riesgos en integraciones históricas</td><td>Medios mixtos y QR sin almacenar PAN</td><td>Ampliado</td></tr><tr><td>Intereses y mora</td><td>Varios cálculos dispersos</td><td>Un motor de intereses</td><td>Ampliado</td></tr><tr><td>Corte de servicio</td><td>Puede ejecutarse solo desde escritorio</td><td>Corte solo con confirmación en campo/red</td><td>Ampliado</td></tr><tr><td>Plan de financiación</td><td>Sí</td><td>Costo financiero total visible; firma en portal</td><td>Ampliado</td></tr><tr><td>Código de barras legacy en transición</td><td>N/A</td><td>Convive en migración sin rechazar pagos</td><td>Nuevo</td></tr></tbody></table><hr><h2 id="img-n11-—-tecnica-redes-y-campo" tabindex="-1">IMG-N11 — Técnica, redes y campo <a class="header-anchor" href="#img-n11-—-tecnica-redes-y-campo" aria-label="Permalink to &quot;IMG-N11 — Técnica, redes y campo&quot;">​</a></h2><p><strong>Título:</strong> Del turno a la conformidad en un flujo</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Factibilidad</td><td>Operaciones &gt; Técnica</td><td>Vigencia definida (ej. 90 días); cobertura de red</td><td>Ampliado</td></tr><tr><td>Orden de trabajo</td><td>Sí</td><td>Mapa; estado visible al socio</td><td>Ampliado</td></tr><tr><td>Instalación internet/TV/tel</td><td>Tablas + técnica</td><td>Aprovisionamiento de red en el mismo recorrido</td><td>Ampliado</td></tr><tr><td>Lectura en campo</td><td>P-Móvil / carga manual</td><td>Foto, offline, motivo de excepción</td><td>Ampliado</td></tr><tr><td>Tercer consumo estimado</td><td>Reglas locales</td><td>Dispara inspección automática</td><td>Ampliado</td></tr><tr><td>Conflictos al sincronizar campo</td><td>Poco supervisados</td><td>Resolución con supervisión</td><td>Ampliado</td></tr><tr><td>Electrodependencia y ventanas de corte</td><td>Parametría</td><td>Reglas normativas por tipo de servicio</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n12-—-los-17-servicios-con-reglas-escritas" tabindex="-1">IMG-N12 — Los 17 servicios con reglas escritas <a class="header-anchor" href="#img-n12-—-los-17-servicios-con-reglas-escritas" aria-label="Permalink to &quot;IMG-N12 — Los 17 servicios con reglas escritas&quot;">​</a></h2><p><strong>Título:</strong> Electricidad, gas, agua… y también sepelio y vivienda</p><p><strong>Texto intro:</strong> En ProCoop las reglas viven en tablas. En CoopApps cada familia de servicio tiene recorrido y controles explícitos.</p><table tabindex="0"><thead><tr><th>Servicio</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Electricidad</td><td>Sí (DEMO)</td><td>Electrodependencia, generación distribuida, ventanas de corte</td><td>Ampliado</td></tr><tr><td>Gas</td><td>Sí</td><td>Reconexión con inspección cuando corresponde</td><td>Ampliado</td></tr><tr><td>Agua</td><td>Sí</td><td>Mínimo vital</td><td>Ampliado</td></tr><tr><td>Cloacas</td><td>Sí</td><td>No asumir “agua = cloaca”</td><td>Ampliado</td></tr><tr><td>Internet / TV / Teléfono</td><td>Sí</td><td>Misma ficha + red</td><td>Ampliado</td></tr><tr><td>Sepelio</td><td>Tablas</td><td>Urgencia no bloqueada solo por deuda</td><td>Ampliado</td></tr><tr><td>Cementerio / parque</td><td>Tablas</td><td>Mora no libera unidad sin regla</td><td>Ampliado</td></tr><tr><td>Vivienda</td><td>Menú planes</td><td>Etapas, vales, seguimiento</td><td>Ampliado</td></tr><tr><td>Capital social</td><td>Tablas</td><td>Integrado al pagar en factura</td><td>Ampliado</td></tr></tbody></table><p><strong>Pie:</strong> Principios comunes nuevos: alta provisoria, suspensión voluntaria, cambio de plan, protecciones normativas no apagables con un switch.</p><hr><h2 id="img-n12b-—-los-17-servicios-complemento" tabindex="-1">IMG-N12b — Los 17 servicios (complemento) <a class="header-anchor" href="#img-n12b-—-los-17-servicios-complemento" aria-label="Permalink to &quot;IMG-N12b — Los 17 servicios (complemento)&quot;">​</a></h2><p><strong>Título:</strong> Todas las familias de servicio, con reglas explícitas (2/2)</p><table tabindex="0"><thead><tr><th>Servicio</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Alumbrado público</td><td>En factura</td><td>Bloque y rendición separados</td><td>Igual / más claro</td></tr><tr><td>Obras / contribución</td><td>Cuotas en factura</td><td>Cuotas con ajuste en la última</td><td>Igual / más claro</td></tr><tr><td>Banco de sangre</td><td>Tablas</td><td>Administración sin datos clínicos</td><td>Ampliado</td></tr><tr><td>Salud / ambulancias</td><td>Tablas</td><td>Gestión administrativa acotada</td><td>Ampliado</td></tr><tr><td>Tasas de terceros</td><td>En comprobante</td><td>Bloque separado y rendición al ente</td><td>Ampliado</td></tr><tr><td>Ortopedia y otros</td><td>Parcial</td><td>Configurable por familia sin programar</td><td>Ampliado</td></tr><tr><td>Telefonía (normas mora)</td><td>Parametría</td><td>Reglas de entrantes y emergencias</td><td>Ampliado</td></tr></tbody></table><p><strong>Por qué importa (gerencia):</strong> Una sola cooperativa multiservicio no improvisa en sepelio lo mismo que en electricidad.</p><hr><h2 id="img-n13-—-integraciones-y-datos-de-la-cooperativa" tabindex="-1">IMG-N13 — Integraciones y datos de la cooperativa <a class="header-anchor" href="#img-n13-—-integraciones-y-datos-de-la-cooperativa" aria-label="Permalink to &quot;IMG-N13 — Integraciones y datos de la cooperativa&quot;">​</a></h2><p><strong>Título:</strong> De credenciales en el programa a integración gobernada</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Credenciales ARCA, pasarelas, correo</td><td>En programa o tablas</td><td>Bóveda; prueba y producción separadas</td><td>Ampliado</td></tr><tr><td>Probar conexión</td><td>Manual</td><td>Botón por integración con diagnóstico</td><td>Ampliado</td></tr><tr><td>Estado “incierto” fiscal/cobro</td><td>Reintentos opacos</td><td>Marcado antes de reintentar comprobante o cobro</td><td>Ampliado</td></tr><tr><td>Exportar a Excel / BI</td><td>Power BI e integra dispersos</td><td>Reportes + exportación; API documentada en etapa final del plan</td><td>Ampliado</td></tr><tr><td>Agente impresoras/lectores</td><td>Mezclado con Agente portal</td><td>Componente dedicado sin copiar socios</td><td>Ampliado</td></tr><tr><td>Tablas fiscales</td><td>Mantenimiento por cooperativa</td><td>Mantenimiento de catálogos fiscales por plataforma</td><td>Ampliado</td></tr><tr><td>Datos para tableros propios</td><td>“Los datos son suyos pero…”</td><td>Indicadores certificados mismos en todos los canales</td><td>Ampliado</td></tr></tbody></table><p><strong>Viñeta ámbar (opcional):</strong> API OpenAPI administrada por la cooperativa — planificada para la última etapa del despliegue; antes: exportaciones y reportes programados.</p><hr><h2 id="img-n14-—-seguridad-y-cumplimiento-verificable" tabindex="-1">IMG-N14 — Seguridad y cumplimiento verificable <a class="header-anchor" href="#img-n14-—-seguridad-y-cumplimiento-verificable" aria-label="Permalink to &quot;IMG-N14 — Seguridad y cumplimiento verificable&quot;">​</a></h2><p><strong>Título:</strong> Estándares actuales, no solo buenas intenciones</p><table tabindex="0"><thead><tr><th>Tema</th><th>Hoy en ProCoop (relevamiento)</th><th>Qué suma CoopApps</th><th>Etiqueta</th></tr></thead><tbody><tr><td>Contraseñas</td><td>Patrones reversibles detectados en código</td><td>Política moderna; doble factor</td><td>Ampliado</td></tr><tr><td>Credenciales en cliente</td><td>Valores fijos en integraciones</td><td>Sin secretos embebidos en apps del socio</td><td>Modelo distinto</td></tr><tr><td>Aislamiento entre cooperativas</td><td>Multitenancy lógico en legacy</td><td>Aislamiento por tenant en nube</td><td>Modelo distinto</td></tr><tr><td>Ley de datos personales</td><td>Implícito</td><td>Diseño alineado a protección de datos</td><td>Ampliado</td></tr><tr><td>Pruebas de seguridad</td><td>Ad hoc</td><td>Referencia OWASP en especificación</td><td>Ampliado</td></tr><tr><td>Privacidad entre convivientes</td><td>Limitada</td><td>Dos titulares, un domicilio, datos separados</td><td>Ampliado</td></tr></tbody></table><hr><h2 id="img-n15-—-los-siete-dolores-del-relevamiento-respuesta" tabindex="-1">IMG-N15 — Los siete dolores del relevamiento (respuesta) <a class="header-anchor" href="#img-n15-—-los-siete-dolores-del-relevamiento-respuesta" aria-label="Permalink to &quot;IMG-N15 — Los siete dolores del relevamiento (respuesta)&quot;">​</a></h2><p><strong>Título:</strong> Lo que pidieron en el primer relevamiento y cómo responde la especificación</p><table tabindex="0"><thead><tr><th>Dolor</th><th>Hoy</th><th>Respuesta CoopApps</th></tr></thead><tbody><tr><td>D1 No está en la nube</td><td>Instalación local</td><td>SaaS multitenant</td></tr><tr><td>D2 Servidores propios</td><td>SQL y agente en la cooperativa</td><td>Sin operar servidores del tenant</td></tr><tr><td>D3 Sin API usable</td><td>Integra sin API por recurso</td><td>API tokenizada (calendario final) + exportaciones antes</td></tr><tr><td>D4 App del socio pobre</td><td>CoopOnline limitado</td><td>Portal/app marca propia; ciclo completo</td></tr><tr><td>D5 Sin identidad de marca</td><td>Web genérica</td><td>Logo, colores, dominio, PWAs</td></tr><tr><td>D6 Seguridad</td><td>Hallazgos en código relevado</td><td>2FA, bóveda, auditoría, estándares</td></tr><tr><td>D7 Soporte ineficiente</td><td>Remoto sin caso</td><td>Ticket, estado, acceso temporal auditado</td></tr></tbody></table><hr><h2 id="img-n15b-—-otros-pedidos-del-relevamiento-marketing-con-prueba" tabindex="-1">IMG-N15b — Otros pedidos del relevamiento (marketing con prueba) <a class="header-anchor" href="#img-n15b-—-otros-pedidos-del-relevamiento-marketing-con-prueba" aria-label="Permalink to &quot;IMG-N15b — Otros pedidos del relevamiento (marketing con prueba)&quot;">​</a></h2><p><strong>Título:</strong> También respondimos lo que el mercado pidió aparte de los “siete dolores”</p><table tabindex="0"><thead><tr><th>Pedido</th><th>Hoy en ProCoop</th><th>Qué suma CoopApps</th><th>Por qué importa</th></tr></thead><tbody><tr><td>Los datos son de la cooperativa (BI propio)</td><td>Exportaciones dispersas</td><td>Exportación tenant + indicadores certificados</td><td>Tableros sin pelearse con Excel</td></tr><tr><td>Diccionario (socio / asociado / usuario)</td><td>Textos fijos</td><td>Diccionario por cooperativa</td><td>La cooperativa habla como su consejo</td></tr><tr><td>Prender/apagar servicios sin programar</td><td>Tablas y consultoría</td><td>Catálogo versionado por familia</td><td>Habilitar sepelio o gas sin proyecto IT</td></tr><tr><td>Copiar config entre servicios/cooperativas</td><td>Manual</td><td>Asistido en catálogo</td><td>Menos meses de parametrización</td></tr><tr><td>Factura masiva con excepciones visibles</td><td>Emisión fuerte, excepciones opacas</td><td>Lote con universo y lista de “no entran”</td><td>Menos reproceso el día de emisión</td></tr><tr><td>Instalación punta a punta</td><td>Tramos en varios menús</td><td>Un recorrido: turno, visita, stock, encuesta</td><td>Menos fricción en venta de internet</td></tr><tr><td>Dos titulares, un domicilio</td><td>Difícil</td><td>Privacidad entre convivientes</td><td>Menos errores y reclamos</td></tr><tr><td>2FA y login moderno</td><td>Básico</td><td>Doble factor en especificación</td><td>Menos cuentas comprometidas</td></tr></tbody></table><hr><h2 id="img-n16-—-escala-de-la-especificacion-sin-tecnicismos-de-implementacion" tabindex="-1">IMG-N16 — Escala de la especificación (sin tecnicismos de implementación) <a class="header-anchor" href="#img-n16-—-escala-de-la-especificacion-sin-tecnicismos-de-implementacion" aria-label="Permalink to &quot;IMG-N16 — Escala de la especificación (sin tecnicismos de implementación)&quot;">​</a></h2><p><strong>Título:</strong> No es “una pantalla nueva”: es un sistema completo especificado</p><table tabindex="0"><thead><tr><th>Concepto</th><th>ProCoop (relevamiento)</th><th>CoopApps (especificación)</th></tr></thead><tbody><tr><td>Menú escritorio catalogado</td><td>120 funciones, 9 pestañas</td><td>119 con destino + reorganización en gestión web</td></tr><tr><td>Pantallas y menús en todas las apps</td><td>—</td><td>Más de 1.000 pantallas; menús reorganizados por proceso</td></tr><tr><td>Requisitos funcionales escritos</td><td>—</td><td>Más de 4.200</td></tr><tr><td>Reglas de negocio documentadas</td><td>Extraídas del código</td><td>Más de 2.600</td></tr><tr><td>Familias de servicio con ficha</td><td>Implícitas en tablas</td><td>17 con recorrido controlado</td></tr><tr><td>Roles plantilla</td><td>Armados a mano</td><td>40 perfiles de partida ajustables</td></tr><tr><td>Fichas de integración</td><td>~23 bloques en relevamiento</td><td>Más de 100 integraciones documentadas</td></tr></tbody></table><p><strong>Por qué importa:</strong> El “más” no es marketing: está escrito en requisitos y olas de construcción.</p><hr><h2 id="img-n17-—-migracion-sin-apagar-un-viernes" tabindex="-1">IMG-N17 — Migración sin apagar un viernes <a class="header-anchor" href="#img-n17-—-migracion-sin-apagar-un-viernes" aria-label="Permalink to &quot;IMG-N17 — Migración sin apagar un viernes&quot;">​</a></h2><p><strong>Título:</strong> Convivencia y cierre por etapas</p><table tabindex="0"><thead><tr><th>Idea</th><th>ProCoop típico</th><th>Qué suma CoopApps</th></tr></thead><tbody><tr><td>Estrategia</td><td>Cambio big bang</td><td>Paralelo factura a factura</td></tr><tr><td>Contabilidad</td><td>Un solo libro</td><td>Libro paralelo hasta conciliar</td></tr><tr><td>Sueldos</td><td>Un solo motor</td><td>Hasta dos meses en paralelo si hace falta</td></tr><tr><td>Corte comercial</td><td>—</td><td>Piloto en etapa intermedia del plan</td></tr><tr><td>Apagado administrativo</td><td>—</td><td>Cuando dos ciclos concilien</td></tr><tr><td>Usuarios del portal</td><td>Re-registro</td><td>Vinculación cuando hay datos exportables</td></tr></tbody></table><hr><h2 id="img-n18-—-matriz-maestra-¿procoop-lo-tiene-20-items-parte-1" tabindex="-1">IMG-N18 — Matriz maestra “¿ProCoop lo tiene?” (20 ítems, parte 1) <a class="header-anchor" href="#img-n18-—-matriz-maestra-¿procoop-lo-tiene-20-items-parte-1" aria-label="Permalink to &quot;IMG-N18 — Matriz maestra “¿ProCoop lo tiene?” (20 ítems, parte 1)&quot;">​</a></h2><p><strong>Título:</strong> Inventario del plus (1/2) — 20 capacidades <strong>Nuevo</strong> o <strong>muy Ampliado</strong> (verificadas en especificación)</p><p>Use tabla 4 columnas: # | Capacidad | ¿ProCoop? | CoopApps</p><p>Filas 1–10 (texto literal): 1 Landing dominio propio | No como producto | Sí<br> 2 Sandbox por cooperativa | No | Sí<br> 3 Espacio empleado separado | No | Sí<br> 4 App campo unificada | Parcial P-Móvil | Sí<br> 5 Quórum asamblea en vivo | No | Sí<br> 6 Incidente masivo único | No | Sí<br> 7 Portal proveedor | No | Sí<br> 8 Anti-fraude CBU | No | Sí<br> 9 Bóveda credenciales | No | Sí<br> 10 Indicadores certificados | No | Sí</p><hr><h2 id="img-n19-—-matriz-maestra-parte-2" tabindex="-1">IMG-N19 — Matriz maestra (parte 2) <a class="header-anchor" href="#img-n19-—-matriz-maestra-parte-2" aria-label="Permalink to &quot;IMG-N19 — Matriz maestra (parte 2)&quot;">​</a></h2><p>Filas 11–20: 11 Comunidad muro/encuestas | Solo SMS | Sí<br> 12 Diccionario por cooperativa | No | Sí<br> 13 Simulación publicación parámetros | No | Sí<br> 14 Expediente digital unificado | Parcial | Sí<br> 15 Trámites web con bandeja operador | Parcial WEB | Sí<br> 16 Autolectura con foto | Limitado | Sí<br> 17 Pago tercero sin ver cuenta ajena | No | Sí<br> 18 Libro sueldo digital habilitado | A veces apagado | Sí<br> 19 Contabilidad automática por operación | Parcial | Sí<br> 20 API administrada cooperativa | No documentada | Plan final + export antes</p><hr><h2 id="img-n20-—-comparativo-de-canales-diagrama-mental" tabindex="-1">IMG-N20 — Comparativo de canales (diagrama mental) <a class="header-anchor" href="#img-n20-—-comparativo-de-canales-diagrama-mental" aria-label="Permalink to &quot;IMG-N20 — Comparativo de canales (diagrama mental)&quot;">​</a></h2><p><strong>Título:</strong> De dos piezas (escritorio + copia) a ocho canales sobre un dato</p><p><strong>Centro:</strong> Una sola información operativa.<br><strong>Alrededor (8 etiquetas):</strong> Gestión web · App socio · Empleados · Campo · Sitio público · Tótem · Plataforma · Integraciones.<br><strong>Hoy (gris):</strong> ProCoop.exe + Agente + CoopOnline/P-Móvil sobre copia.<br><strong>Por qué importa:</strong> Menos reclamos, menos reprocesos, más canales sin multiplicar verdades.</p><hr><h2 id="img-n21-—-que-no-decir-en-la-reunion-honestidad" tabindex="-1">IMG-N21 — Qué NO decir en la reunión (honestidad) <a class="header-anchor" href="#img-n21-—-que-no-decir-en-la-reunion-honestidad" aria-label="Permalink to &quot;IMG-N21 — Qué NO decir en la reunión (honestidad)&quot;">​</a></h2><p><strong>Título:</strong> Frases prohibidas y cómo decirlo bien</p><table tabindex="0"><thead><tr><th>Evitar</th><th>Decir</th></tr></thead><tbody><tr><td>“ProCoop no tiene app”</td><td>“Tiene CoopOnline y P-Móvil; están limitados por la copia y poca marca propia.”</td></tr><tr><td>“API desde el día 1”</td><td>“Exportaciones y reportes al inicio; API documentada en la etapa final del plan.”</td></tr><tr><td>“Mismas pantallas”</td><td>“Mismo negocio; pantallas web y reglas adicionales.”</td></tr><tr><td>“Sin ProCoop mañana”</td><td>“Migración por olas con convivencia.”</td></tr></tbody></table><hr><h2 id="img-n23-—-una-frase-por-audiencia-slide-comercial" tabindex="-1">IMG-N23 — Una frase por audiencia (slide comercial) <a class="header-anchor" href="#img-n23-—-una-frase-por-audiencia-slide-comercial" aria-label="Permalink to &quot;IMG-N23 — Una frase por audiencia (slide comercial)&quot;">​</a></h2><p><strong>Título:</strong> Por qué importa, según quién mira</p><table tabindex="0"><thead><tr><th>Audiencia</th><th>Frase visible (marketing honesto)</th></tr></thead><tbody><tr><td>Consejo</td><td>Menos riesgo de parque, datos y reputación; migración por etapas, no apagón.</td></tr><tr><td>Gerencia general</td><td>Una sola verdad para oficina, campo y socio; decisiones con números iguales en todos lados.</td></tr><tr><td>Atención y ventas</td><td>Marca propia, trámites con expediente y plazos; el socio deja de “cazar” el saldo.</td></tr><tr><td>Facturación y mora</td><td>Lotes controlados, un motor de intereses, corte solo confirmado.</td></tr><tr><td>Técnica y campo</td><td>Una app, obra visible para el socio, serie del equipo en domicilio.</td></tr><tr><td>Contador y auditoría</td><td>Trazas, libro sueldo digital, asientos desde operaciones.</td></tr><tr><td>Socio</td><td>Pagar, reclamar y dar de baja con la marca de su cooperativa, sobre la misma cuenta que ve caja.</td></tr></tbody></table><p><strong>Gancho central:</strong> ProCoop probó que el negocio se puede; CoopApps lo especifica para la nube y el siglo XXI digital del socio.</p><hr><h2 id="img-n22-—-cierre-ejecutivo" tabindex="-1">IMG-N22 — Cierre ejecutivo <a class="header-anchor" href="#img-n22-—-cierre-ejecutivo" aria-label="Permalink to &quot;IMG-N22 — Cierre ejecutivo&quot;">​</a></h2><p><strong>Título:</strong> CoopApps = ProCoop en alcance + plataforma moderna</p><p>Checklist visual (6 ✓):</p><ol><li>Menú relevado cubierto (119/120) — detalle en deck IMG-F.</li><li><strong>Ocho aplicativos</strong> frente a escritorio + copia.</li><li><strong>Marca y app del socio</strong> con dato único.</li><li><strong>Más funciones</strong> sin botón en ProCoop (comunidad, asamblea, proveedor, sandbox…).</li><li><strong>Migración</strong> sin big bang.</li><li><strong>Datos exportables</strong> y camino a API propia.</li></ol><hr><h2 id="c-orden-sugerido-al-generar" tabindex="-1">C. Orden sugerido al generar <a class="header-anchor" href="#c-orden-sugerido-al-generar" aria-label="Permalink to &quot;C. Orden sugerido al generar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Orden</th><th>Código</th><th>Uso en reunión</th></tr></thead><tbody><tr><td>1</td><td>N00, N01</td><td>Abrir</td></tr><tr><td>2</td><td>N02, N20</td><td>Ocho apps</td></tr><tr><td>3</td><td>N03–N05</td><td>Plataforma y “sin botón”</td></tr><tr><td>4</td><td>N06–N07</td><td>Socio</td></tr><tr><td>5</td><td>N08–N11</td><td>Gestión y operación</td></tr><tr><td>6</td><td>N12</td><td>17 servicios</td></tr><tr><td>7</td><td>N13–N14</td><td>Datos y seguridad</td></tr><tr><td>8</td><td>N15</td><td>Dolores</td></tr><tr><td>9</td><td>N16–N17</td><td>Escala y migración</td></tr><tr><td>10</td><td>N12b</td><td>17 servicios completo</td></tr><tr><td>11</td><td>N15b</td><td>Pedidos extra del relevamiento</td></tr><tr><td>12</td><td>N18–N19</td><td>Inventario 20 ítems (anexo denso)</td></tr><tr><td>13</td><td>N23</td><td>Frases por audiencia (comercial)</td></tr><tr><td>14</td><td>N21–N22</td><td>Honestidad y cierre</td></tr></tbody></table><hr><h2 id="d-relacion-con-otros-materiales" tabindex="-1">D. Relación con otros materiales <a class="header-anchor" href="#d-relacion-con-otros-materiales" aria-label="Permalink to &quot;D. Relación con otros materiales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesidad</th><th>Archivo</th></tr></thead><tbody><tr><td>Menú 120 ítems Hoy vs CoopApps</td><td><code>comparativo-funcional-megaspec-unificado.md</code> + IMG-F</td></tr><tr><td>Comparativo corto consejo</td><td><code>comparativo-funcional-procoop-vs-coopapps-PROMPT-CLAUDE-COMPLETO.md</code> (IMG-C)</td></tr><tr><td>Dolores antes/después</td><td><code>dolores-procoop-antes-y-despues.md</code> (IMG-D)</td></tr><tr><td><strong>Este deck: lo nuevo</strong></td><td><strong>Este archivo</strong> (IMG-N)</td></tr><tr><td><strong>Lista por aplicativo (1 línea/funcción)</strong></td><td><a href="./enumeracion-funciones-por-aplicativo"><code>enumeracion-funciones-por-aplicativo.md</code></a></td></tr></tbody></table>`,132)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
